{
  "pou_name": "FixtureMotorStartStop",
  "pou_type": "FUNCTION_BLOCK",
  "declaration": "FUNCTION_BLOCK FixtureMotorStartStop
VAR_INPUT
	StartBtn : BOOL;
	StopBtn : BOOL;
	EStop : BOOL;
END_VAR
VAR_OUTPUT
	Motor : BOOL;
END_VAR
VAR
	lState : BOOL := FALSE;
END_VAR",
  "implementation": "BEGIN
	IF StopBtn OR EStop THEN
		lState := FALSE;
	ELSIF StartBtn THEN
		lState := TRUE;
	END_IF;

	Motor := lState;
END"
}
